import type { SpeechDTO } from '@shared/types';
import { ChillMusic } from './ChillMusic';

interface Item extends SpeechDTO {
  receivedAt: number;
}

/** Announcements older than this are skipped (the moment has passed). */
const STALE_MS = 25_000;

/**
 * Plays the server's voice announcements one at a time.
 * Audio comes from /api/tts/:id (Edge Online or Windows offline voice, generated by the server),
 * played through the page so OBS captures it ("Control audio via OBS"). The music is ducked while speaking.
 * Queue: limited length; when full the least important / oldest announcement is dropped.
 */
export class VoicePlayer {
  private static instance: VoicePlayer | null = null;
  static get(): VoicePlayer {
    if (!VoicePlayer.instance) VoicePlayer.instance = new VoicePlayer();
    return VoicePlayer.instance;
  }

  private queue: Item[] = [];
  private playing = false;
  private current: HTMLAudioElement | null = null;
  private opts = { enabled: true, volume: 0.9, maxQueue: 4 };
  private locked = false;
  private listeners = new Set<(locked: boolean) => void>();

  setOptions(o: Partial<typeof this.opts>) {
    this.opts = { ...this.opts, ...o };
    if (this.current) this.current.volume = this.opts.volume;
    if (!this.opts.enabled) this.stopAll();
    this.trim();
  }

  isLocked() {
    return this.locked;
  }

  onLockChange(fn: (locked: boolean) => void) {
    this.listeners.add(fn);
    return () => this.listeners.delete(fn);
  }

  private setLocked(v: boolean) {
    if (this.locked === v) return;
    this.locked = v;
    for (const l of this.listeners) l(v);
  }

  /** Call from a click / key press: browsers block audio until the first user gesture. */
  unlock() {
    if (!this.locked) return;
    this.setLocked(false);
    void this.next();
  }

  enqueue(s: SpeechDTO) {
    if (!this.opts.enabled) return;
    this.queue.push({ ...s, receivedAt: Date.now() });
    this.trim();
    void this.next();
  }

  /** Admin "Nghe thử": speak any text right away (skips the queue). */
  preview(text: string) {
    this.stopAll();
    return this.playUrl(`/api/tts/preview?text=${encodeURIComponent(text)}`);
  }

  stopAll() {
    this.queue = [];
    if (this.current) {
      this.current.pause();
      this.current = null;
    }
    this.playing = false;
    ChillMusic.get().duck(false);
  }

  private trim() {
    while (this.queue.length > this.opts.maxQueue) {
      let drop = 0;
      for (let i = 1; i < this.queue.length; i++) {
        const a = this.queue[i];
        const b = this.queue[drop];
        if (a.priority < b.priority || (a.priority === b.priority && a.receivedAt < b.receivedAt)) drop = i;
      }
      this.queue.splice(drop, 1);
    }
  }

  private take(): Item | null {
    const now = Date.now();
    this.queue = this.queue.filter((q) => now - q.receivedAt < STALE_MS);
    if (!this.queue.length) return null;
    // Most important first; same importance → oldest first.
    let best = 0;
    for (let i = 1; i < this.queue.length; i++) {
      const a = this.queue[i];
      const b = this.queue[best];
      if (a.priority > b.priority || (a.priority === b.priority && a.receivedAt < b.receivedAt)) best = i;
    }
    return this.queue.splice(best, 1)[0];
  }

  private async next() {
    if (this.playing || this.locked || !this.opts.enabled) return;
    const item = this.take();
    if (!item) return;
    this.playing = true;
    // Warm the server cache for the following announcement while this one plays.
    const following = this.queue[0];
    if (following) fetch(`/api/tts/${following.id}`).catch(() => {});
    try {
      await this.playUrl(`/api/tts/${item.id}`);
    } catch (e) {
      if ((e as Error).name === 'NotAllowedError') {
        // Autoplay blocked: keep it for when the page gets a click.
        this.queue.unshift(item);
        this.setLocked(true);
      } else {
        await this.browserFallback(item.text);
      }
    } finally {
      this.playing = false;
      ChillMusic.get().duck(false);
    }
    if (!this.locked) setTimeout(() => void this.next(), 250);
  }

  private playUrl(url: string): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      const a = new Audio(url);
      a.volume = this.opts.volume;
      this.current = a;
      let done = false;
      const finish = (err?: Error) => {
        if (done) return;
        done = true;
        if (this.current === a) this.current = null;
        if (err) reject(err);
        else resolve();
      };
      a.addEventListener('playing', () => ChillMusic.get().duck(true));
      a.addEventListener('ended', () => finish());
      a.addEventListener('error', () => finish(new Error('Không tải được giọng đọc')));
      a.play().catch((e: Error) => finish(e));
      // Safety net: never block the queue forever.
      setTimeout(() => {
        if (!done) {
          a.pause();
          finish(new Error('timeout'));
        }
      }, 30_000);
    });
  }

  /** Last resort when the server cannot synthesize: the browser's own Vietnamese voice, if any. */
  private browserFallback(text: string): Promise<void> {
    const synth = window.speechSynthesis;
    const voice = synth?.getVoices().find((v) => v.lang.toLowerCase().startsWith('vi'));
    if (!synth || !voice) return Promise.resolve();
    return new Promise<void>((resolve) => {
      const u = new SpeechSynthesisUtterance(text);
      u.voice = voice;
      u.lang = voice.lang;
      u.volume = this.opts.volume;
      u.onend = () => resolve();
      u.onerror = () => resolve();
      ChillMusic.get().duck(true);
      synth.speak(u);
    });
  }
}
